def safe_open(path, mode, default):
    try:
        with open(path, mode, encoding='utf-8') as f:
            return f.read()
    except (FileNotFoundError, IOError):
        return default

if __name__ == '__main__':
    print(safe_open(('config.json', 'r', None)))

